// Generated by scripts/bundle_rules.py. Edit default-rules.js instead.
/* exported defaultRules */
function defaultRules(ruleId) {
  /* exported RULES */
  // Packaged default rules. Keep IDs stable; edit settings and conditions here.
  const RULES = [
    // To add a rule, uncomment this template and give it a unique stable ID.
    // {
    //   id: 'new-rule',
    //   name: 'My new rule',
    //   enabled: true,
    //   urlMatch: 'example.com',
    //   x: null,
    //   y: null,
    //   gridSize: 1,
    //   step: 10,
    //   intervalMs: 30,
    //   visualize: true,
    //   condition() {
    //     // Replace this with your condition and coordinates.
    //     return false;
    //   },
    // },
  ];

  // You can also append rules with RULES.push({ ... }).
  RULES.push({
    id: 'cf-turnstile-click',
    name: 'Auto click cf',
    enabled: true,
    urlMatch: '*',
    x: null,
    y: null,
    gridSize: 10,
    step: 10,
    intervalMs: 80,
    visualize: true,
    condition() {
      const cf =
        [...document.querySelectorAll('meta')].filter((x) =>
          x.content.includes('challenges.cloudflare.com'),
        ).length > 0;
      if (!cf) return false;

      const rectBox = document.querySelectorAll('.main-content div')?.[1];
      if (!rectBox) return false;
      const rect = rectBox.getBoundingClientRect();
      return {
        x: parseInt(rect.left + 30),
        y: parseInt(rect.top + 30),
      };
    },
  });

  /* exported evaluateRules */
  // Runtime behavior lives here; default-rules.js is only configuration.
  function evaluateRules(rules, ruleId) {
    if (ruleId === undefined) {
      return rules.map(({ condition, ...rule }) =>
        condition ? { ...rule, ruleType: 'bundled', builtinId: rule.id } : rule,
      );
    }
    // Normalize here so promises cannot be implicitly awaited by executeScript.
    try {
      const value = rules.find((rule) => rule.id === ruleId)?.condition?.();
      if (value === true) return true;
      if (!value || typeof value !== 'object' || typeof value.then === 'function')
        return false;
      const x = value.x ?? value.X;
      const y = value.y ?? value.Y;
      return Number.isFinite(x) && Number.isFinite(y) && x >= 0 && y >= 0
        ? { x, y }
        : false;
    } catch (error) {
      console.warn('[clickyphus] built-in rule failed:', error);
      return false;
    }
  }

  return evaluateRules(RULES, ruleId);
}
